#!/bin/bash
# Download the graphs into $BENCH_DATA (skips files already present):
#   hpc/fetch_data.sh                 every graph of the benchmarks, about 5 GB
#   hpc/fetch_data.sh G67 wing ...    only these (quick.sh does this)
# Synthetic graphs (grids, random geometric, Barabasi-Albert, Erdos-Renyi, hypercubes) are generated by bench/ at run time.
set -eo pipefail
source "$(dirname "$0")/env.sh"
mkdir -p $BENCH_DATA/gr $BENCH_DATA/co $BENCH_DATA/mtx && cd $BENCH_DATA
get() { [ -s "$2" ] && return 0; echo "  downloading $1"; curl -fsSL --retry 3 -o "$2.part" "$1" && mv "$2.part" "$2"; }

SNAP_ALL="roadNet-PA roadNet-TX roadNet-CA email-Enron ca-HepTh ca-GrQc wiki-Vote cit-HepPh email-EuAll p2p-Gnutella31 soc-Epinions1"
SUITESPARSE_ALL="USpowerGrid c-42 c-69 G67 delaunay_n14 delaunay_n16 fe_sphere fe_tooth wing t60k onera_dual \
  luxembourg_osm belgium_osm oilpan lpl1 finan512 net4-1 nd6k OPF_6000 delaunay_n13 CurlCurl_0 \
  598a fe_ocean usroads-48 delaunay_n17 rgg_n_2_17_s0 144 wave Dubcova3 c-73 cont-300 thermomech_dM delaunay_n19"
SYNTHETIC="EB_8192_256 EB_16384_64 rgg2d_14 rgg3d_14 hypercube_14"

snap() { get https://snap.stanford.edu/data/$1.txt.gz $1.txt.gz; }
dimacs() {   # a 9th DIMACS challenge road network (travel times) and its coordinates
  local D=http://www.diag.uniroma1.it/challenge9/data r=$1
  [ -s gr/USA-road-t_$r.gr ] || { get $D/USA-road-t/USA-road-t.$r.gr.gz gr/USA-road-t.$r.gr.gz; gunzip -c gr/USA-road-t.$r.gr.gz > gr/USA-road-t_$r.gr; rm gr/USA-road-t.$r.gr.gz; }
  [ -s co/USA-road-d.$r.co ] || { get $D/USA-road-d/USA-road-d.$r.co.gz co/USA-road-d.$r.co.gz; gunzip -f co/USA-road-d.$r.co.gz; }
}
suitesparse() {   # a SuiteSparse matrix (its group looked up in the collection's index)
  local m=$1 grp
  [ -s mtx/$m/$m.mtx ] && return 0
  get https://sparse.tamu.edu/files/ssstats.csv mtx/ssstats.csv
  grp=$(awk -F, -v m=$m '$2 == m {print $1; exit}' mtx/ssstats.csv)
  [ -n "$grp" ] || { echo "  ERROR: $m not in the SuiteSparse index"; exit 1; }
  get https://sparse.tamu.edu/MM/$grp/$m.tar.gz mtx/$m.tar.gz
  tar -xzf mtx/$m.tar.gz -C mtx && rm mtx/$m.tar.gz
}
netrepo() {       # Fast-APSP's web graph, from Network Repository, in the SuiteSparse layout
  [ -s mtx/web-sk-2005/web-sk-2005.mtx ] && return 0
  get https://nrvis.com/download/data/web/web-sk-2005.zip mtx/web-sk-2005.zip
  mkdir -p mtx/web-sk-2005 && unzip -o -q mtx/web-sk-2005.zip web-sk-2005.mtx -d mtx/web-sk-2005 && rm mtx/web-sk-2005.zip
}
one() {           # one graph, by the name bench/graphs.jl uses
  case " $SNAP_ALL " in *" $1 "*) snap $1; return ;; esac
  case " $SYNTHETIC " in *" $1 "*) return ;; esac
  case $1 in USA-t-*) dimacs ${1#USA-t-} ;; web-sk-2005) netrepo ;; *) suitesparse $1 ;; esac
}

if [ $# -gt 0 ]; then
  for g in "$@"; do one $g; done
  echo "data for $* in $BENCH_DATA"; exit 0
fi
echo "SNAP edge lists"; for g in $SNAP_ALL; do snap $g; done
echo "9th DIMACS challenge road networks (travel times) and their coordinates"; for r in $DIMACS; do dimacs $r; done
echo "SuiteSparse matrices"; for m in $SUITESPARSE_ALL; do suitesparse $m; done
echo "Network Repository (Fast-APSP's web graph)"; netrepo
echo "data complete in $BENCH_DATA"
